import csv
import io
import unittest

from exports import export_tickets


class ExportTicketsTests(unittest.TestCase):
    def test_empty_rows(self):
        self.assertEqual(export_tickets([]), b"")

    def test_serializes_unicode_special_values_and_missing_fields(self):
        rows = [
            {"id": 1, "title": "登录失败, 请重试", "note": '他说 "稍后"\n已跟进'},
            {"id": 2, "title": "中文", "status": "open"},
        ]

        result = export_tickets(rows)

        self.assertEqual(
            result,
            (
                "id,title,note,status\r\n"
                '1,"登录失败, 请重试","他说 ""稍后""\n已跟进",\r\n'
                "2,中文,,open\r\n"
            ).encode("utf-8"),
        )
        self.assertEqual(
            list(csv.DictReader(io.StringIO(result.decode("utf-8"), newline=""))),
            [
                {
                    "id": "1",
                    "title": "登录失败, 请重试",
                    "note": '他说 "稍后"\n已跟进',
                    "status": "",
                },
                {"id": "2", "title": "中文", "note": "", "status": "open"},
            ],
        )


if __name__ == "__main__":
    unittest.main()
